var documenterSearchIndex = {"docs":
[{"category":"section","location":"#AWSCS3.jl","page":"Home","text":"AWSCS3 is a lightweight, high-performance Julia client for S3-compatible object storage (AWS S3, etc.). Built on the AWS C SDK for maximum throughput.","title":"AWSCS3.jl"},{"category":"section","location":"#Installation","page":"Home","text":"If you haven't installed our local registry yet, do that first:\n\n] registry add https://github.com/bhftbootcamp/Green.git\n\nTo install AWSCS3, simply use the Julia package manager:\n\n] add AWSCS3","title":"Installation"},{"category":"section","location":"#Usage","page":"Home","text":"Here is a basic example of working with an S3-compatible service:\n\nusing AWSCS3\n\nclient = S3Client(\n    host = \"s3.amazonaws.com\",\n    region = \"us-east-1\",\n    access_key = ENV[\"AWS_ACCESS_KEY_ID\"],\n    secret_key = ENV[\"AWS_SECRET_ACCESS_KEY\"],\n)\n\nbucket_exists(client, \"my-bucket\") || create_bucket(client, \"my-bucket\")\n\nput_object(client, \"my-bucket\", \"demo/hello.txt\", \"Hello, World!\")\nput_object(client, \"my-bucket\", \"demo/data.bin\", UInt8[0x01, 0x02, 0x03, 0x04])\n\nbody = get_object(client, \"my-bucket\", \"demo/hello.txt\") |> String\n\nfor obj in list_objects(client, \"my-bucket\"; prefix = \"demo/\")\n    println(\"$(obj.key) ($(obj.size) bytes)\")\nend\n\ncopy_object(client, \"my-bucket\", \"demo/hello.txt\", \"my-bucket\", \"demo/hello_copy.txt\")\ndelete_objects(client, \"my-bucket\", [\"demo/hello.txt\", \"demo/hello_copy.txt\", \"demo/data.bin\"])\n\nclose(client)","title":"Usage"},{"category":"section","location":"#Using-S3Config","page":"Home","text":"You can also create a client from a configuration struct:\n\nusing AWSCS3\n\ncfg = S3Config(\n    host = \"localhost:9000\",\n    region = \"us-east-1\",\n    access_key = \"admin\",\n    secret_key = \"admin123\",\n    tls = false,\n)\n\nclient = S3Client(cfg)\n\n# ... use client ...\n\nshutdown!(client)","title":"Using S3Config"},{"category":"section","location":"#Do-block-pattern","page":"Home","text":"The do-block pattern automatically shuts down the client when the block exits:\n\nusing AWSCS3\n\nS3Client(\n    host = \"localhost:9000\",\n    region = \"us-east-1\",\n    access_key = \"admin\",\n    secret_key = \"admin123\",\n    tls = false,\n) do client\n    create_bucket(client, \"my-bucket\")\n    put_object(client, \"my-bucket\", \"key.txt\", \"value\")\n    body = get_object(client, \"my-bucket\", \"key.txt\") |> String\nend","title":"Do-block pattern"},{"category":"section","location":"#Pagination","page":"Home","text":"Use list_objects_detailed for paginated listings:\n\nresult = list_objects_detailed(client, \"my-bucket\"; max_keys = 100)\n\nfor obj in result.objects\n    println(\"$(obj.key) ($(obj.size) bytes)\")\nend\n\nif result.is_truncated\n    next_page = list_objects_detailed(\n        client, \"my-bucket\";\n        max_keys = 100,\n        continuation_token = result.continuation_token,\n    )\nend","title":"Pagination"},{"category":"section","location":"#Error-handling","page":"Home","text":"All operations throw AbstractS3Error subtypes on failure:\n\ntry\n    get_object(client, \"my-bucket\", \"nonexistent-key\")\ncatch e::S3ObjectNotFoundError\n    println(\"Object '$(e.key)' not found in bucket '$(e.bucket)'\")\nend","title":"Error handling"},{"category":"section","location":"pages/api_reference/#API-Reference","page":"API Reference","text":"","title":"API Reference"},{"category":"section","location":"pages/api_reference/#Client","page":"API Reference","text":"","title":"Client"},{"category":"section","location":"pages/api_reference/#Operations","page":"API Reference","text":"","title":"Operations"},{"category":"section","location":"pages/api_reference/#Buckets","page":"API Reference","text":"","title":"Buckets"},{"category":"section","location":"pages/api_reference/#Objects","page":"API Reference","text":"","title":"Objects"},{"category":"section","location":"pages/api_reference/#Result-Types","page":"API Reference","text":"","title":"Result Types"},{"category":"section","location":"pages/api_reference/#Errors","page":"API Reference","text":"","title":"Errors"},{"category":"type","location":"pages/api_reference/#AWSCS3.S3Config","page":"API Reference","text":"S3Config\n\nConfiguration for creating an S3Client.\n\nFields\n\nhost::String: S3 endpoint hostname (e.g. \"s3.amazonaws.com\").\nregion::String: AWS region.\naccess_key::String: Access key ID.\nsecret_key::String: Secret access key.\nuser_agent::String: User agent string (default \"AWSCS3.jl\").\nconnect_timeout_ms::Int: Connection timeout in milliseconds (default 3000).\ntls::Bool: Whether to use TLS (default true).\n\n\n\n\n\n","title":"AWSCS3.S3Config"},{"category":"type","location":"pages/api_reference/#AWSCS3.S3Client","page":"API Reference","text":"S3Client\n\nClient for AWS S3-compatible storage. Manages connections, credentials, and request lifecycle via the AWS C SDK.\n\nConstructors\n\nS3Client(; host, region, access_key, secret_key, ...) — create from keyword arguments.\nS3Client(cfg::S3Config) — create from an S3Config.\nS3Client(f::Function; kwargs...) — executes f(client) then calls shutdown!.\n\nExamples\n\nS3Client(\n    host = \"s3.amazonaws.com\",\n    region = \"us-east-1\",\n    access_key = ENV[\"AWS_ACCESS_KEY_ID\"],\n    secret_key = ENV[\"AWS_SECRET_ACCESS_KEY\"],\n) do client\n    put_object(client, \"my-bucket\", \"hello.txt\", \"Hello, World!\")\n    body = get_object(client, \"my-bucket\", \"hello.txt\") |> String\n    objects = list_objects(client, \"my-bucket\"; prefix = \"hello\")\n    delete_object(client, \"my-bucket\", \"hello.txt\")\nend\n\n\n\n\n\n","title":"AWSCS3.S3Client"},{"category":"method","location":"pages/api_reference/#Base.isopen-Tuple{S3Client}","page":"API Reference","text":"Base.isopen(client::S3Client) -> Bool\n\nCheck whether client has not been shut down.\n\n\n\n\n\n","title":"Base.isopen"},{"category":"function","location":"pages/api_reference/#AWSCS3.shutdown!","page":"API Reference","text":"shutdown!(client::S3Client)\n\nRelease all resources held by client. Safe to call multiple times.\n\n\n\n\n\n","title":"AWSCS3.shutdown!"},{"category":"function","location":"pages/api_reference/#AWSCS3.create_bucket","page":"API Reference","text":"create_bucket(client::S3Client, bucket::String; ignore_existing::Bool = false)\n\nCreate a bucket. When ignore_existing is true, an existing bucket is treated as success.\n\n\n\n\n\n","title":"AWSCS3.create_bucket"},{"category":"function","location":"pages/api_reference/#AWSCS3.delete_bucket","page":"API Reference","text":"delete_bucket(client::S3Client, bucket::String; force::Bool = false)\n\nDelete a bucket. When force is true, all objects are deleted first via delete_all_objects!.\n\n\n\n\n\n","title":"AWSCS3.delete_bucket"},{"category":"function","location":"pages/api_reference/#AWSCS3.bucket_exists","page":"API Reference","text":"bucket_exists(client::S3Client, bucket::String) -> Bool\n\nCheck whether a bucket exists.\n\n\n\n\n\n","title":"AWSCS3.bucket_exists"},{"category":"function","location":"pages/api_reference/#AWSCS3.list_buckets","page":"API Reference","text":"list_buckets(client::S3Client) -> Vector{String}\n\nList all bucket names accessible by the client.\n\n\n\n\n\n","title":"AWSCS3.list_buckets"},{"category":"function","location":"pages/api_reference/#AWSCS3.set_bucket_versioning","page":"API Reference","text":"set_bucket_versioning(client::S3Client, bucket::String; enabled::Bool = true)\n\nEnable or suspend versioning for a bucket.\n\n\n\n\n\n","title":"AWSCS3.set_bucket_versioning"},{"category":"function","location":"pages/api_reference/#AWSCS3.put_object","page":"API Reference","text":"put_object(client::S3Client, bucket::String, key::String, body; headers = [], metadata = [])\n\nUpload an object to bucket under key. The body can be a String, Vector{UInt8}, IOStream, or any IO.\n\nKeyword Arguments\n\nheaders: Additional HTTP headers.\nmetadata: User-defined metadata stored as x-amz-meta-<key>.\n\n\n\n\n\n","title":"AWSCS3.put_object"},{"category":"function","location":"pages/api_reference/#AWSCS3.get_object","page":"API Reference","text":"get_object(client::S3Client, bucket::String, key::String) -> Vector{UInt8}\nget_object(client::S3Client, bucket::String, key::String, dest_path::AbstractString)\n\nDownload an object. Returns the body as bytes, or saves it to a file at dest_path.\n\n\n\n\n\n","title":"AWSCS3.get_object"},{"category":"function","location":"pages/api_reference/#AWSCS3.delete_object","page":"API Reference","text":"delete_object(client::S3Client, bucket::String, key::String; version_id = nothing)\n\nDelete an object. Pass version_id to delete a specific version when versioning is enabled.\n\n\n\n\n\n","title":"AWSCS3.delete_object"},{"category":"function","location":"pages/api_reference/#AWSCS3.delete_objects","page":"API Reference","text":"delete_objects(client::S3Client, bucket::String, keys::Vector{String})\n\nDelete a list of objects from bucket using S3's batched DeleteObjects API. Keys are split into batches of up to 1000 per request. Throws on the first per-object failure reported by the service.\n\n\n\n\n\n","title":"AWSCS3.delete_objects"},{"category":"function","location":"pages/api_reference/#AWSCS3.copy_object","page":"API Reference","text":"copy_object(client, src_bucket, src_key, dest_bucket, dest_key; kwargs...) -> S3CopyResult\n\nCopy an object from src_bucket/src_key to dest_bucket/dest_key.\n\nKeyword Arguments\n\nsrc_version_id: Copy a specific source version.\nheaders: Additional HTTP headers.\nmetadata: User-defined metadata to set on the destination object.\n\n\n\n\n\n","title":"AWSCS3.copy_object"},{"category":"function","location":"pages/api_reference/#AWSCS3.object_exists","page":"API Reference","text":"object_exists(client::S3Client, bucket::String, key::String) -> Bool\n\nCheck whether an object exists.\n\n\n\n\n\n","title":"AWSCS3.object_exists"},{"category":"function","location":"pages/api_reference/#AWSCS3.list_objects","page":"API Reference","text":"list_objects(client::S3Client, bucket::String; kwargs...) -> Vector{S3Object}\n\nList objects in a bucket.\n\nKeyword Arguments\n\nprefix: Restrict results to keys with this prefix.\ndelimiter: Group keys by delimiter to return common prefixes.\ncontinuation_token: Token from a previous listing to continue.\nmax_keys: Maximum number of keys to return.\n\n\n\n\n\n","title":"AWSCS3.list_objects"},{"category":"function","location":"pages/api_reference/#AWSCS3.list_objects_detailed","page":"API Reference","text":"list_objects_detailed(client::S3Client, bucket::String; kwargs...) -> S3ListResult\n\nList objects with pagination info.\n\nKeyword Arguments\n\nprefix: Restrict results to keys with this prefix.\ndelimiter: Group keys by delimiter to return common prefixes.\ncontinuation_token: Token from a previous listing to continue.\nmax_keys: Maximum number of keys to return.\n\n\n\n\n\n","title":"AWSCS3.list_objects_detailed"},{"category":"function","location":"pages/api_reference/#AWSCS3.delete_all_objects!","page":"API Reference","text":"delete_all_objects!(client::S3Client, bucket::String)\n\nDelete all objects in a bucket using batched multi-object delete requests.\n\n\n\n\n\n","title":"AWSCS3.delete_all_objects!"},{"category":"type","location":"pages/api_reference/#AWSCS3.S3Object","page":"API Reference","text":"S3Object\n\nS3 object metadata returned by list operations.\n\nFields\n\nkey::String: Object key.\nsize::Int: Object size in bytes.\nlast_modified::String: Last modification timestamp.\netag::String: Entity tag.\n\n\n\n\n\n","title":"AWSCS3.S3Object"},{"category":"type","location":"pages/api_reference/#AWSCS3.S3ListResult","page":"API Reference","text":"S3ListResult\n\nResult from list_objects_detailed with pagination info.\n\nFields\n\nobjects::Vector{S3Object}: Listed objects.\ncommon_prefixes::Vector{String}: Common prefixes when using a delimiter.\nis_truncated::Bool: Whether more results are available.\ncontinuation_token::Union{Nothing,String}: Token for the next page.\n\n\n\n\n\n","title":"AWSCS3.S3ListResult"},{"category":"type","location":"pages/api_reference/#AWSCS3.S3CopyResult","page":"API Reference","text":"S3CopyResult\n\nResult from copy_object.\n\nFields\n\netag::String: Entity tag of copied object.\nlast_modified::String: Last modification timestamp.\n\n\n\n\n\n","title":"AWSCS3.S3CopyResult"},{"category":"type","location":"pages/api_reference/#AWSCS3.AbstractS3Error","page":"API Reference","text":"AbstractS3Error <: Exception\n\nAbstract base type for all S3-related exceptions.\n\nConcrete subtypes:\n\nS3Error: Generic S3 error response.\nS3AccessDeniedError: Access denied (HTTP 403).\nS3BucketAlreadyExistsError: Bucket already exists (HTTP 409).\nS3BucketNotFoundError: Bucket not found (HTTP 404).\nS3BucketNotEmptyError: Bucket is not empty (HTTP 409).\nS3ObjectNotFoundError: Object not found (HTTP 404).\nS3InvalidRequestError: Invalid request (HTTP 400).\nS3ServerError: Server error (HTTP 5xx).\nS3ConnectionError: Connection failure.\nS3AuthenticationError: Authentication failure (HTTP 401/403).\n\n\n\n\n\n","title":"AWSCS3.AbstractS3Error"},{"category":"type","location":"pages/api_reference/#AWSCS3.S3Error","page":"API Reference","text":"S3Error <: AbstractS3Error\n\nRepresents a generic S3 error response when a more specific subtype is not applicable.\n\nFields\n\noperation::String: Operation name.\nstatus::Int: HTTP status code, or 0 if unavailable.\nerror_code::Int: AWS SDK error code, or 0.\ncode::Union{Nothing,String}: S3 error code.\nmessage::String: Human-readable error message.\nrequest_id::Union{Nothing,String}: Request ID from the service.\nresource::Union{Nothing,String}: Resource associated with the error.\nraw_body::Vector{UInt8}: Raw response body.\n\n\n\n\n\n","title":"AWSCS3.S3Error"},{"category":"type","location":"pages/api_reference/#AWSCS3.S3AccessDeniedError","page":"API Reference","text":"S3AccessDeniedError <: AbstractS3Error\n\nAccess denied while performing an operation on a resource.\n\nFields\n\noperation::String: Operation name.\nresource::String: Resource path.\nmessage::String: Error message.\n\n\n\n\n\n","title":"AWSCS3.S3AccessDeniedError"},{"category":"type","location":"pages/api_reference/#AWSCS3.S3BucketAlreadyExistsError","page":"API Reference","text":"S3BucketAlreadyExistsError <: AbstractS3Error\n\nBucket already exists.\n\nFields\n\nbucket::String: Bucket name.\n\n\n\n\n\n","title":"AWSCS3.S3BucketAlreadyExistsError"},{"category":"type","location":"pages/api_reference/#AWSCS3.S3BucketNotFoundError","page":"API Reference","text":"S3BucketNotFoundError <: AbstractS3Error\n\nBucket was not found.\n\nFields\n\nbucket::String: Bucket name.\noperation::String: Operation name.\n\n\n\n\n\n","title":"AWSCS3.S3BucketNotFoundError"},{"category":"type","location":"pages/api_reference/#AWSCS3.S3BucketNotEmptyError","page":"API Reference","text":"S3BucketNotEmptyError <: AbstractS3Error\n\nBucket is not empty.\n\nFields\n\nbucket::String: Bucket name.\n\n\n\n\n\n","title":"AWSCS3.S3BucketNotEmptyError"},{"category":"type","location":"pages/api_reference/#AWSCS3.S3ObjectNotFoundError","page":"API Reference","text":"S3ObjectNotFoundError <: AbstractS3Error\n\nObject was not found in a bucket.\n\nFields\n\nbucket::String: Bucket name.\nkey::String: Object key.\noperation::String: Operation name.\n\n\n\n\n\n","title":"AWSCS3.S3ObjectNotFoundError"},{"category":"type","location":"pages/api_reference/#AWSCS3.S3InvalidRequestError","page":"API Reference","text":"S3InvalidRequestError <: AbstractS3Error\n\nThe request was rejected as invalid.\n\nFields\n\noperation::String: Operation name.\nmessage::String: Error message.\n\n\n\n\n\n","title":"AWSCS3.S3InvalidRequestError"},{"category":"type","location":"pages/api_reference/#AWSCS3.S3ServerError","page":"API Reference","text":"S3ServerError <: AbstractS3Error\n\nThe server returned a 5xx error.\n\nFields\n\noperation::String: Operation name.\nstatus::Int: HTTP status code.\nmessage::String: Error message.\n\n\n\n\n\n","title":"AWSCS3.S3ServerError"},{"category":"type","location":"pages/api_reference/#AWSCS3.S3ConnectionError","page":"API Reference","text":"S3ConnectionError <: AbstractS3Error\n\nFailed to connect to the S3 endpoint.\n\nFields\n\nhost::String: Endpoint hostname.\nmessage::String: Error message.\n\n\n\n\n\n","title":"AWSCS3.S3ConnectionError"},{"category":"type","location":"pages/api_reference/#AWSCS3.S3AuthenticationError","page":"API Reference","text":"S3AuthenticationError <: AbstractS3Error\n\nAuthentication failed for the request.\n\nFields\n\noperation::String: Operation name.\nmessage::String: Error message.\n\n\n\n\n\n","title":"AWSCS3.S3AuthenticationError"}]
}
